(() => {
  const incoming = new URLSearchParams(location.search).get('invite');
  if(incoming && /^\d{11}$/.test(incoming)){sessionStorage.setItem('cw_referral',incoming);location.hash='#/register';}
  const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money = value => '₹'+Number(value || 0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
  const assets={people:'agent-commission',code:'inbox',chart:'notebook',money:'balance',filter:'filter',rules:'receipt',support:'customer-headset',rebate:'money-bag'};
  const icon=name=>'<img class="promo-icon" src="assets/promotion-icons/'+(assets[name] || assets.chart)+'.svg" alt="" aria-hidden="true">';
  const rows = [['rewards','Partner rewards','people'],['code','Copy invitation code','code'],['subordinates','Subordinate data','chart'],['commission','Commission detail','money'],['rules','Invitation rules','rules'],['support','Agent line customer service','support'],['rebate','Rebate ratio','rebate']];
  function invitationShare(panel,code,link,copy,toast){
    panel.classList.add('promo-invitation-panel');
    panel.innerHTML=`<p class="invite-swipe">Swipe left or right to choose your poster</p><div class="invite-posters" tabindex="0" aria-label="Invitation posters">${['Your Color Win team','Invite friends together','Share. Invite. Grow.'].map((title,i)=>`<article class="invite-poster invite-poster-${i}"><img src="assets/web%20images/colorwin-invite-banner.png" alt="Color Win referral poster"><div><strong>${title}</strong><span class="invite-qr" data-invite-qr></span><small>Invitation code <b>${esc(code)}</b></small></div></article>`).join('')}</div><h2 class="invite-title">Invite friends to Color Win</h2><button type="button" id="invite-download">DOWNLOAD QR CODE</button><button type="button" id="promo-copy-link">Copy invitation link</button><p class="invite-share-label">Share to other apps to invite friends</p><div class="invite-socials">${[['WhatsApp','wa'],['Telegram','tg'],['Facebook','fb'],['X','x']].map(([label,id])=>`<button type="button" data-invite-social="${id}"><img src="assets/social/${{wa:'whatsapp',tg:'telegram',fb:'facebook',x:'x'}[id]}.png" alt="" width="40" height="40">${label}</button>`).join('')}</div><button type="button" id="promo-share">Share link</button>`;
    const qr=panel.querySelectorAll('[data-invite-qr]');
    if(window.QRCode)qr.forEach(node=>new window.QRCode(node,{text:link,width:128,height:128,colorDark:'#170b29',colorLight:'#ffffff',correctLevel:window.QRCode.CorrectLevel.M}));
    panel.querySelector('#promo-copy-link').onclick=()=>copy(link);
    panel.querySelector('#invite-download').onclick=()=>{const canvas=qr[0].querySelector('canvas');if(!canvas){toast('QR code unavailable. Copy the invitation link instead.',true);return;}const output=document.createElement('canvas');output.width=output.height=160;const drawing=output.getContext('2d');drawing.fillStyle='#fff';drawing.fillRect(0,0,160,160);drawing.drawImage(canvas,16,16);const anchor=document.createElement('a');anchor.href=output.toDataURL('image/png');anchor.download='colorwin-invitation-'+code+'.png';anchor.click();};
    panel.querySelector('#promo-share').onclick=async()=>{if(navigator.share){try{await navigator.share({title:'Join Color Win',text:'Join my Color Win team',url:link});}catch(error){if(error.name!=='AbortError')toast('Unable to share. Copy the link instead.',true);}}else await copy(link);};
    panel.querySelectorAll('[data-invite-social]').forEach(button=>button.onclick=()=>{const encoded=encodeURIComponent(link),message=encodeURIComponent('Join my Color Win team: '+link);const destinations={wa:'https://wa.me/?text='+message,tg:'https://t.me/share/url?url='+encoded+'&text='+encodeURIComponent('Join Color Win'),fb:'https://www.facebook.com/sharer/sharer.php?u='+encoded,x:'https://twitter.com/intent/tweet?text='+message};window.open(destinations[button.dataset.inviteSocial],'_blank','noopener,noreferrer');});
  }
  function view(tabbar,route='#/promotion'){
    const campaigns=window.ColorWinOperations?.config?.campaigns||[];
    const action=route.split('/')[2];
    if(action){const title=action==='new'?'New subordinates':action==='link'?'Invitation link':(rows.find(row=>row[0]===action)?.[1] || 'Promotion');return '<section class="promotion-page promo-subpage" data-promo-sub="'+esc(action)+'"><header class="promo-header"><a href="#/promotion" aria-label="Back to promotion"><svg class="promo-back-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="m15 5-7 7 7 7"/></svg></a><h1>'+title+'</h1><span class="promo-header-spacer"></span></header><main class="promo-sub-content"><section id="promo-panel" class="promo-panel" tabindex="-1"><p>Loading…</p></section><p id="promo-status" role="status"></p><button type="button" hidden data-promo="'+esc(action)+'"></button></main></section>';}
    return `<section class="promotion-page"><header class="promo-header"><a href="#/home" aria-label="Home"><svg class="promo-back-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="m15 5-7 7 7 7"/></svg></a><h1>Agency</h1><button type="button" data-promo="new" aria-label="New subordinates">${icon('filter')}</button></header><div class="promo-hero"><div class="promo-orbit"></div><span>Yesterday's total commission</span><p>Invite friends. Grow your Color Win team.</p></div><main class="promo-content">${campaigns.map(c=>`<section class="promo-panel"><h2>${esc(c.title)}</h2><p>${esc(c.description)}</p></section>`).join('')}<section class="promo-stat-card" aria-label="Subordinate statistics"><div class="promo-stat-head"><span>Direct subordinates</span><span>Team subordinates</span></div><div class="promo-stat-columns" id="promo-stats"><p>Loading promotion data…</p></div></section><button type="button" class="promo-invite" data-promo="link">INVITATION LINK</button><p id="promo-status" role="status"></p><div class="promo-menu">${rows.map(([id,label,image])=>`<button type="button" class="promo-row" data-promo="${id}">${icon(image)}<span>${label}</span>${id==='code'?'<small id="promo-code">—</small><svg class="promo-code-copy" viewBox="0 0 24 24" aria-hidden="true"><rect x="8" y="3" width="13" height="14" rx="2"/><path d="M16 17v4H3V7h5"/></svg>': '<b aria-hidden="true">›</b>'}</button>`).join('')}</div><section class="promo-data"><h2>${icon('chart')} Promotion data</h2><div id="promo-totals" class="promo-total-grid"><span>Loading…</span></div></section></main>${tabbar}</section>`;}
  async function bind(toast){
    const page=document.querySelector('.promotion-page');let data=null;
    const panel=page.querySelector('#promo-panel');
    const sub=page.dataset.promoSub;
    const show=(title,body)=>{if(!panel)return;panel.innerHTML='<h2>'+title+'</h2>'+body;};
    const url=()=>{const link=new URL(location.href);link.search='';link.searchParams.set('invite',data.invitation_code);link.hash='/register';return link.href;};
    async function copy(value){if(!value){toast('Invitation code unavailable.',true);return;}try{await navigator.clipboard.writeText(String(value));toast('Copied successfully');}catch{const field=document.createElement('textarea');field.value=String(value);field.style.cssText='position:fixed;left:0;top:0;opacity:0';document.body.append(field);field.select();const copied=document.execCommand('copy');field.remove();toast(copied?'Copied successfully':'Unable to copy. Please try again.',!copied);}}
    page.querySelectorAll('[data-promo]').forEach(button=>button.onclick=async()=>{
      const action=button.dataset.promo;
      if(!sub){if(action==='code'){await copy(data?.invitation_code);return;}location.hash="#/promotion/"+action;return;}
      if(["new","rewards","subordinates","commission","rules","support","rebate"].includes(action)){window.ColorWinPromotionPages.mount(action,panel,data,{copy,url});return;}
      if(action==='code'||action==='link'){
        if(!data?.invitation_code){toast('Invitation code unavailable. Retry after database setup.',true);return;}
        if(action==='code'){show('Your invitation code','<div class="promo-empty">'+icon('code')+'</div><strong class="promo-large-code">'+esc(data.invitation_code)+'</strong><p>Use this code to invite friends to your team.</p><button type="button" id="promo-copy-code">Copy invitation code</button>');panel.querySelector('#promo-copy-code').onclick=()=>copy(data.invitation_code);return;}
        invitationShare(panel,data.invitation_code,url(),copy,toast);return;
      }
      if(action==='subordinates'){
        if(!data){toast('Promotion data unavailable.',true);return;}
        show('Subordinate data',`<p>Direct invitations · ${(data.direct || []).length} members</p>${data.direct?.length?data.direct.map(member=>`<article class="promo-member"><div><strong>UID ${esc(member.uid)}</strong><span>${esc(member.phone_last4?'******'+member.phone_last4:'Phone unavailable')}</span></div><dl><div><dt>Deposit amount</dt><dd>${money(member.deposit_amount)}</dd></div><div><dt>Deposits</dt><dd>${Number(member.deposit_count)}</dd></div></dl><small>Joined ${esc(new Date(member.created_at).toLocaleDateString('en-IN'))}</small></article>`).join(''):'<div class="promo-empty"><img class="cw-no-data-art" src="assets/no-data.svg" alt="" aria-hidden="true"><h3>No invited users yet</h3><p>Share your invitation link. Friends who register with your code appear here.</p></div>'}`);return;
      }
      const details={rules:['Invitation rules','Every member receives a unique 11-digit invitation code. Share your link to open registration with your code filled in. A successful registration permanently links the new account to its inviter. Only completed, verified deposits count. Direct subordinates are people you invite; team subordinates include their invitation network.'],rewards:['Partner rewards','Partner reward levels have not been configured yet.'],commission:['Commission detail','Commission calculation and payment rules have not been configured yet.'],rebate:['Rebate ratio','Rebate rates have not been configured yet.'],support:['Agent line customer service','An agent support contact has not been configured yet.']};
      const [title,body]=details[action];show(title,`<p>${body}</p>`);
    });
    if(['rules','support','rebate'].includes(sub)){window.ColorWinPromotionPages.mount(sub,panel,null,{copy,url});return;}
    try{
      data=await window.ColorWinAuth.promotion();if(!page.isConnected)return;
      if(sub){page.querySelector('[data-promo]').click();return;}
      page.querySelector('#promo-code').textContent=data.invitation_code;
      const stats=s=>`<div><strong>${Number(s.registers || 0)}</strong><span>Number of register</span><strong class="promo-purple">${Number(s.deposit_count || 0)}</strong><span>Deposit number</span><strong class="promo-gold">${money(s.deposit_amount).replace(/^₹/,'').replace(/\.00$/,'')}</strong><span>Deposit amount</span><strong>${Number(s.first_deposits || 0)}</strong><span>Number of people making first deposit</span></div>`;
      page.querySelector('#promo-stats').innerHTML=stats(data.direct_stats)+stats(data.team_stats);
      page.querySelector('#promo-totals').innerHTML=`<div><strong>${Number(data.this_week || 0)}</strong><span>This week's registrations</span></div><div><strong>—</strong><span>Total commission</span></div><div><strong>${Number(data.direct_stats.registers || 0)}</strong><span>Direct subordinate</span></div><div><strong>${Number(data.team_stats.registers || 0)}</strong><span>Total team subordinates</span></div>`;
    }catch(error){if(!page.isConnected)return;page.querySelector('#promo-status').textContent=error.message;if(sub)show('Unable to load','<p>Please retry.</p>');else{page.querySelector('#promo-stats').innerHTML='<p>Unable to load statistics.</p>';page.querySelector('#promo-totals').innerHTML='<p>Data unavailable</p>';}const retry=document.createElement('button');retry.type='button';retry.textContent='Retry';retry.onclick=()=>window.dispatchEvent(new Event('hashchange'));page.querySelector('#promo-status').append(' ',retry);}
  }
  window.ColorWinPromotion={view,bind,referral:()=>sessionStorage.getItem('cw_referral') || ''};
})();
